#include "ksStateFlashCommitTask.h"
#include <iostream>
#include <stdexcept>
using T=ks::StateFlashCommitTask;void check(bool b,const char* w){if(!b)throw std::runtime_error(w);}
int main(){try{uint64_t cases=0;for(unsigned pending=0;pending<65536;++pending){T task;unsigned clocks=0,reads=0,writes=0,children=0;auto read=[&](){++reads;return pending;};auto write=[&](uint16_t value){check(value==0&&!children&&!reads,"Pending clear order differs");++writes;};while(!task.complete()){if(task.awaitingChild()){check(task.child()==(children?T::Child::Idle:T::Child::Program),"Flash callback order differs");++children;check(task.resumeChild(),"Flash callback rejected");continue;}const auto c=task.nextClocks(),before=reads,stores=writes;check(!task.advanceBefore(c-1,read,write)&&reads==before&&writes==stores,"Flash early observation");check(task.advanceBefore(c,read,write)==c,"Flash admission differs");clocks+=c;}check(clocks==153+unsigned(pending!=0)*20&&reads==1&&writes==1&&children==1+unsigned(pending!=0)&&!task.resumeChild(),"Flash completion/clocks differ");++cases;}std::cout<<"PASS: "<<cases<<" complete flash commit jobs/all16bitpending/clear-program-observe-idle order/exact clocks/deadlines\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
